package com.emp.ems;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1") @Transactional(readOnly=true)
public class AttendanceController{private final EmployeeRepository employees;private final AttendanceRepository attendance;private final LeaveRepository leaves;AttendanceController(EmployeeRepository employees,AttendanceRepository attendance,LeaveRepository leaves){this.employees=employees;this.attendance=attendance;this.leaves=leaves;}record LeaveInput(@NotBlank @Pattern(regexp="Vacation|Paid leave|Sick leave")String type,@NotNull LocalDate startDate,@NotNull LocalDate endDate,@Size(max=500)String reason){}record Review(@NotBlank @Pattern(regexp="Approved|Rejected")String status){}
 @PostMapping("/employee/attendance/clock-in")@ResponseStatus(HttpStatus.CREATED)@Transactional Attendance.View clockIn(@AuthenticationPrincipal CurrentUser user){Employee e=employees.lockById(user.id()).orElseThrow();if(attendance.findByEmployeeIdAndClockOutIsNull(e.id).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already clocked in.");Attendance a=new Attendance();a.employee=e;a.clockIn=Instant.now();a.logDate=LocalDate.now(ZoneOffset.UTC);return attendance.save(a).view();}
 @PostMapping("/employee/attendance/clock-out")@Transactional Attendance.View clockOut(@AuthenticationPrincipal CurrentUser user){employees.lockById(user.id()).orElseThrow();Attendance a=attendance.findByEmployeeIdAndClockOutIsNull(user.id()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"You are not clocked in."));a.clockOut=Instant.now();return a.view();}
 @GetMapping("/employee/attendance/current")ResponseEntity<Attendance.View> current(@AuthenticationPrincipal CurrentUser user){return attendance.findByEmployeeIdAndClockOutIsNull(user.id()).map(a->ResponseEntity.ok(a.view())).orElseGet(()->ResponseEntity.noContent().build());}
 @GetMapping("/employee/attendance")PageResponse<Attendance.View> ownAttendance(@AuthenticationPrincipal CurrentUser user,Pageable page){return PageResponse.of(attendance.findByEmployeeId(user.id(),PeopleController.bounded(page,"clockIn",true)).map(Attendance::view));}
 @GetMapping("/admin/attendance")PageResponse<Attendance.View> all(Pageable page){return PageResponse.of(attendance.findAll(PeopleController.bounded(page,"clockIn",true)).map(Attendance::view));}
 @GetMapping("/employee/leaves")PageResponse<LeaveRequest.View> ownLeaves(@AuthenticationPrincipal CurrentUser user,Pageable page){return PageResponse.of(leaves.findByEmployeeId(user.id(),PeopleController.bounded(page,"startDate",true)).map(LeaveRequest::view));}
 @GetMapping("/admin/leaves")PageResponse<LeaveRequest.View> leaves(Pageable page){return PageResponse.of(leaves.findAll(PeopleController.bounded(page,"startDate",true)).map(LeaveRequest::view));}
 @GetMapping("/admin/attendance/timeline")PageResponse<LeaveRequest.View> timeline(@RequestParam LocalDate from,@RequestParam LocalDate until,Pageable page){validateDates(from,until);return PageResponse.of(leaves.timeline(from,until,PeopleController.bounded(page,"startDate",false)).map(LeaveRequest::view));}
 @PostMapping("/employee/leaves")@ResponseStatus(HttpStatus.CREATED)@Transactional LeaveRequest.View request(@AuthenticationPrincipal CurrentUser user,@Valid @RequestBody LeaveInput input){validateDates(input.startDate(),input.endDate());Employee e=employees.lockById(user.id()).orElseThrow();if(leaves.overlaps(e.id,input.startDate(),input.endDate()))throw new ResponseStatusException(HttpStatus.CONFLICT,"You already have a request for these dates.");LeaveRequest l=new LeaveRequest();l.employee=e;l.type=input.type();l.startDate=input.startDate();l.endDate=input.endDate();l.reason=input.reason();return leaves.save(l).view();}
 @PatchMapping("/admin/leaves/{id}")@Transactional LeaveRequest.View review(@PathVariable UUID id,@Valid @RequestBody Review review){LeaveRequest l=leaves.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found."));if(!l.status.equals("Pending"))throw new ResponseStatusException(HttpStatus.CONFLICT,"This request has already been reviewed.");l.status=review.status();return l.view();}
 static void validateDates(LocalDate from,LocalDate until){if(until.isBefore(from)||until.isAfter(from.plusYears(1)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an end date within one year after the start date.");}
}
